      for (let sub = 0; sub < TASK.substeps && !st.reason; sub++) integrate(st, act, params, TASK.dt / TASK.substeps);
      const aAct = {
        x: (st.vel.x - vPrev.x) / TASK.dt,
        y: (st.vel.y - vPrev.y) / TASK.dt,
        z: (st.vel.z - vPrev.z) / TASK.dt,
