      const k = i + shift;
      ilcAcc[i].x = clamp(ilcAcc[i].x + 5.0 * posErr[k].x + 0.35 * accErr[k].x, -6, 6);
      ilcAcc[i].y = clamp(ilcAcc[i].y + 5.0 * posErr[k].y + 0.35 * accErr[k].y, -6, 6);
      ilcAcc[i].z = clamp(ilcAcc[i].z + 5.0 * posErr[k].z + 0.35 * accErr[k].z, -6, 6);
    }
  }
